import { useEffect, useRef } from 'react'

type Callback = () => void

/**
 * Execute callback interval in react function components.
 * @param callback
 * @param delay
 */
export function useInterval(callback: Callback, delay: number): void {
  const callbackRef = useRef<Callback>(callback)

  useEffect(() => {
    callbackRef.current = callback
  }, [callback])

  useEffect(() => {
    const tick: Callback = () => {
      if (callbackRef.current === undefined) return
      callbackRef.current()
    }
    const id = setInterval(tick, delay)
    return () => clearInterval(id)
  }, [delay])
}

import { useEffect, useRef } from 'react'

/**
 * Use previous state.
 * @param value
 * @returns
 */
export function usePreviousState<T = unknown>(value: T): T {
  const ref = useRef<T>(value)
  useEffect(() => {
    ref.current = value
  }, [value])
  return ref.current
}

import type React from 'react'
import { useEffect, useRef } from 'react'

/**
 * Create a reactive ref which will follow the changes of the given data.
 * @param data
 * @returns
 */
export function useReactiveRef<T>(data: T): React.MutableRefObject<T> {
  const ref = useRef(data)
  useEffect(() => {
    ref.current = data
  }, [data])
  return ref
}

const Container = styled.div`
  padding: 1rem;

  div {
    display: flex;
    justify-content: space-between;
    align-items: center;
    text-align: center;
    min-width: 8rem;

    button {
      flex: 0 0 auto;
      user-select: none;
    }

    span {
      flex: 1 1 3rem;
      color: #e37878;
    }
  }

  h2 {
    padding-top: 1rem;
    border-top: 1px solid #ccc;
    margin: 1rem auto 0;
    text-align: center;
  }
`

function usePreviousState(value, defaultValue) {
  const ref = React.useRef(defaultValue)

  React.useEffect(() => {
    ref.current = value
  }, [value])

  console.log('[usePreviousState] value: ', value, 'current:', ref.current)
  return ref.current
}

function Component() {
  const [count, setCount] = React.useState(0)
  const prevCount = usePreviousState(count, -1)

  return (
    <Container>
      <div>
        <button onClick={ () => setCount(c => c - 1) }>-</button>
        <span>{ count }</span>
        <button onClick={ () => setCount(c => c + 1) }>+</button>
      </div>
      <h2>before: {prevCount} </h2>
    </Container>
  )
}

render(<Component />)

